import{_ as i,o as a,c as t,a2 as o}from"./chunks/framework.DwAI3uWn.js";const u=JSON.parse('{"title":"Game Performance Triage  Challenge","description":"Pre-Act4","frontmatter":{"title":"Game Performance Triage  Challenge","description":"Pre-Act4","source":"docs/archive/source-material/Game Performance Triage  Challenge.md","category":"Archive","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/source-material/game-performance-triage-challenge.md","filePath":"content/docs/archive/source-material/game-performance-triage-challenge.md"}'),n={name:"content/docs/archive/source-material/game-performance-triage-challenge.md"};function s(r,e,l,c,p,d){return a(),t("div",null,[...e[0]||(e[0]=[o('<div><h1 id="document-title">Game Performance Triage Challenge<a class="header-anchor" href="#document-title" aria-label="Link to title">​</a></h1><p>Pre-Act4</p><p>Activity 4: Game Performance Triage</p><p>Challenge</p><p>Group # 13</p><p>BSIT - GD - J4S</p><p>Group Members: Luis M. Cabrido Iii Sherwin P. Limosnero Sean Matthew Lee Narvaez Christian Jude N. Villaber</p><p>PROFESSOR: Grache Elizal C. Greta</p><p>P a g e | 1</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Part I. Scenario Understanding Points: 10 Complete the table below. Item Group Answer Selected Scenario Chainy: A 3D World Educational Game for Learning</p><p>Emerging Technology (Blockchain &amp; AI)</p><p>Main Purpose of the Game To introduce fundamental concepts of blockchain and artificial intelligence to young beginners through an interactive 3D top-down exploration game and puzzle activities.</p><p>Target Users Elementary learners aged 6 to 12 years old (Grades 1 to 6) in Cryptita Plays outreach programs and community mini-libraries.</p><p>Main User Inputs Multi-touch gestures: on-screen virtual joystick movement, tapping to interact with 3D nodes/NPCs, drag-and-drop actions for classification puzzles, and UI button presses for quizzes.</p><p>Expected Outputs Real-time top-down 3D visuals, animated characters, visual validation and tamper-alert cues, AI data sorting feedback, background audio/SFX, star ratings, and unlockable badges.</p><p>Data or Files to be Stored Local JSON save files storing level completion flags, earned badges, quiz answers, player profile records, and custom audio/graphics settings.</p><p>Part II. Memory Requirement Analysis Points: 20 Identify the parts of the game that may consume memory while running. Game Element or Resource Possible Memory Use Why It May Affect Performance</p><p>Images or Visual Assets High (UI sprites, texture atlases, 3D surface textures)</p><p>High-resolution or uncompressed textures consume excessive mobile VRAM/RAM, causing frame rate drops on budget devices.</p><p>Audio or Sound Effects Low to Moderate (BGM loops, button clicks, puzzle feedback audio)</p><p>Loading multiple uncompressed sound files directly into memory increases the baseline RAM footprint.</p><p>P a g e | 2</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Game Objects or Characters</p><p>High (3D player avatar, interactive puzzle blocks, environment props)</p><p>Continuously instantiating and destroying 3D GameObjects increases heap memory and triggers frequent Garbage Collection (GC) spikes.</p><p>Scores or Player Progress Very Low (Numeric score tallies, completion booleans, earned badge arrays)</p><p>Minimal memory footprint; only impacts memory if dangling references cause leaks across scene transitions.</p><p>Levels or Scenes Moderate to High (The</p><p>3 distinct 3D educational levels with props and colliders)</p><p>Retaining previous scene assets in memory while loading new levels leads to cumulative RAM bloat.</p><p>Other Resource Moderate (Particle effects, UI shader buffers)</p><p>Dense particle bursts during reward sequences can overload mobile GPU fill rates.</p><p>Answer briefly:</p><ol><li>Which part of the game will most likely consume the most memory? The 3D environment assets, including 3D meshes, materials, and texture maps loaded during world exploration.</li><li>What may happen if the device has limited RAM? The Android operating system&#39;s Low Memory Killer (LMK) may force-close the app due to Out-Of-Memory exceptions, or the game will stutter heavily during Garbage Collection sweeps.</li><li>How can the group reduce memory usage? Adopt low-poly 3D models, compress all textures to ASTC/ETC2 mobile formats, use Object Pooling for recurring puzzle blocks, and unload unused scene assets between level transitions. Part III. Application Performance Diagnosis Points: 25 Complete the performance diagnosis table. Possible Issue Likely Cause Recommended Solution Slow loading Synchronous loading of heavy 3D assets, textures, and audio files all at once at startup.</li></ol><p>Implement asynchronous scene loading (Addressables / AsyncOperation) with a visual progress bar.</p><p>Lag or delayed response High draw call counts, unbatched materials, and complex mesh</p><p>Enable static/dynamic batching, combine textures into atlases, and replace mesh colliders with primitive box/sphere colliders</p><p>P a g e | 3</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies colliders running physics checks. Freezing or crashing Memory leaks from undisposed objects and frequent GC allocations inside update loops.</p><p>Cache component references, remove memory allocations from Update(), and profile heap usage.</p><p>High storage usage Uncompressed raw audio files and unoptimized 3D mesh files included in the installation package.</p><p>Compress audio to .ogg/.mp3, strip unused engine packages, and optimize 3D geometry in Blender.</p><p>Poor performance on low-end devices Dynamic real-time shadows, unbaked lighting, and heavy post-processing shaders</p><p>Pre-bake all static lighting into lightmaps, use mobile unlit/vertex-lit shaders, and lock the frame rate to 30 FPS.</p><p>Answer briefly:</p><ol><li>What should be tested before releasing the game? Test for a stable 30 FPS frame rate on physical budget Android test units, verify touch control responsiveness, check battery temperature, and ensure local save data persists across app restarts</li><li>What device limitation may affect the game most? Limited RAM (2 GB to 3 GB) and lower-tier mobile GPUs commonly found in entry-level Android devices deployed in community libraries.</li><li>What is the most practical performance improvement for the scenario? Pre-baking all scene lighting into lightmaps and using stylized low-poly assets to eliminate dynamic lighting calculations and minimize draw calls. Part IV. Networking Requirement Analysis Points: 25 Decide whether the game should be: ● Offline ● Online ● Hybrid Complete the table below. Networking Requirement Group Answer Recommended Setup: Offline, Online, or Hybrid Offline (Standalone Local Execution with</li></ol><p>Optional Hybrid Telemetry)</p><p>P a g e | 4</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Reason for Recommendation Outreach beneficiary sites and community mini-libraries often lack stable or affordable internet connectivity. The entire educational curriculum must work reliably without an active connection.</p><p>Data to be Sent, if applicable Optional lightweight JSON payloads containing level completion status, quiz scores, and badge timestamps for analytics. Data to be Received, if applicable Optional remote curriculum updates or new</p><p>quiz question packs.</p><p>Client-Server Communication Needed? No for core gameplay. All game logic, puzzle checking, and progression systems run locally on the client device.</p><p>API Needed? No for gameplay. (Optional HTTPS REST endpoint if batch score syncing is added in the future).</p><p>Possible Network Problem Connection drops, high packet latency, or complete lack of Wi-Fi during community outreach sessions.</p><p>Recommended Solution Bundle all 3D assets, levels, audio, and quiz databases directly within the standalone mobile APK build, storing all player records locally.</p><p>Answer briefly:</p><ol><li>Can the game still be useful without internet access? Explain. Yes, 100% useful. All three educational levels, interactive puzzle mechanics (transaction validation, tamper detection, AI classification), and quizzes are stored locally on the device.</li><li>What feature would require internet access? Only non-essential secondary features, such as remote student analytics synchronization for educators or downloading future expanded lesson packs.</li><li>What should happen if the connection is slow or unavailable? The application should silently bypass network operations without interrupting gameplay or displaying blocking error popups, keeping all progress safely saved on local storage.</li></ol><p>P a g e | 5</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Part V. Final Technical Recommendation Points: 20 Write a short recommendation for the scenario. Chainy is technically feasible for elementary learners (ages 6 to 12) provided the development team adheres strictly to an offline-first and mobile-optimized architecture. Because target users at Cryptita Plays community mini-libraries and outreach centers primarily use entry-level Android devices with 2 GB to 3 GB of RAM, the system must avoid server dependencies and heavy real-time networking. The most significant technical risk involves memory usage and rendering overhead from 3D assets on low-end mobile hardware. To ensure smooth execution, the team must simplify visual complexity by using stylized low-poly 3D models, pre-baking all static lighting into lightmaps, and compressing textures using ASTC formats. Real-time dynamic shadows and memory allocations inside update loops must be eliminated in favor of object pooling. The game must remain strictly offline for its core release, bundling all three educational levels (Blockchain Verification, Tamper Detection, and AI Classification) directly inside the installation package. Development should prioritize building a functional, optimized MVP with responsive touch controls before considering any secondary online features. Minimum answer: 120 words Your recommendation must answer:</p><ol><li>Is the game technically feasible for the target users? Yes, Chainy is technically feasible for learners aged 6 to 12 at Cryptita Plays mini-library sites, provided that the application is built using lightweight mobile rendering practices and tested directly on budget Android devices.</li><li>What should be simplified or optimized? The team must optimize 3D model polygon counts, compress texture atlases using mobile ASTC formats, pre-bake all static lighting instead of using real-time dynamic shadows, and implement object pooling for interactive puzzle blocks. The gameplay mechanics should also simplify complex technical jargon into intuitive, visual cause-and-effect puzzles.</li><li>Should the game be offline, online, or hybrid? The game should be strictly offline for its core release. All 3D levels, interactive mini-games, and quiz question databases must be bundled directly inside the local APK build so learning is never blocked by unstable community internet connections.</li><li>What is the most important technical risk? The biggest technical risk is excessive memory usage and GPU rendering strain on budget Android hardware (devices with 2 GB to 4 GB of RAM). Unoptimized 3D meshes, high draw calls, or memory leaks could trigger severe frame rate drops or force-close the app via Out-Of-Memory exceptions.</li><li>What should the development team prioritize first? The development team must prioritize building and profiling a functional, mobile-optimized Minimum Viable Product (MVP) containing the core interactive levels (transaction validation, tamper detection, and AI classification) with responsive touch controls before expanding scope or adding secondary features.</li></ol></div>',1)])])}const h=i(n,[["render",s]]);export{u as __pageData,h as default};
